"""Build a searchable offline HTML reader and a GitHub Markdown index. Requires Pandoc."""
from pathlib import Path
from html import escape
import hashlib, json, os, re, subprocess
from urllib.parse import unquote, quote
from bs4 import BeautifulSoup

ROOT=Path(__file__).resolve().parents[1]
CSS='''*{box-sizing:border-box}body{overflow-wrap:anywhere}select{max-width:100%}body{margin:0;color:#20382e;background:#f5f7f3;font:17px/1.7 system-ui,sans-serif}header{padding:18px 5%;background:white;border-bottom:1px solid #ccd7ca}a{color:#245c40;text-underline-offset:3px}main{max-width:1200px;margin:auto;padding:32px 24px 70px}h1{font-size:clamp(28px,4vw,42px);line-height:1.2}h2{margin-top:2em}nav{display:flex;gap:20px;flex-wrap:wrap}article{max-width:90ch;margin:auto;overflow-wrap:anywhere}input,select{font:inherit;padding:12px;border:1px solid #80917e;border-radius:5px;background:white;color:#20382e}input{flex:1;min-width:180px}.controls{display:flex;gap:12px;flex-wrap:wrap;margin:28px 0}li{margin:14px 0}#results{list-style:none;padding:0}#results li{padding:18px 0;border-top:1px solid #ccd7ca}small,.meta{color:#53654e;font-size:13px}pre{background:#e8eedf;padding:18px;overflow:auto;white-space:pre-wrap}code{font-size:.86em}img{max-width:100%;height:auto}table{display:block;overflow-x:auto;border-collapse:collapse;font-size:14px}td,th{border:1px solid #ccd7ca;padding:9px}blockquote{margin:20px 0;background:#e8eedf;padding:16px 22px}summary{cursor:pointer}button{font:inherit}#count{min-height:2em}:focus-visible{outline:3px solid #507638;outline-offset:3px}@media(max-width:650px){main{padding:24px 16px}input,select{width:100%}nav{gap:12px}pre{font-size:13px;padding:10px}}@media print{header,.controls{display:none}body{background:white}main{padding:0}}'''

def relative(target, parent):return quote(os.path.relpath(target,parent).replace(os.sep,'/'),safe='/#')
def shell(title,body,parent):
    return '<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+escape(title)+'</title><style>'+CSS+'</style></head><body><header><nav><a href="'+relative(ROOT/'index.html',parent)+'">MBA · 4ABL</a><a href="'+relative(ROOT/'biblioteca/index.html',parent)+'">Biblioteca e busca</a><a href="'+relative(ROOT/'biblioteca/README.md',parent)+'">Índice Markdown</a></nav></header><main>'+body+'</main></body></html>'

def main():
    lib=ROOT/'biblioteca';lib.mkdir(exist_ok=True)
    entries=json.loads((ROOT/'catalogo/biblioteca.json').read_text())
    pending=json.loads((ROOT/'catalogo/pendencias-conversao.json').read_text())
    disciplines=json.loads((ROOT/'catalogo/disciplinas.json').read_text())
    names={d['id']:d['nome_exibido'] for d in disciplines};names['geral']='Materiais gerais'
    meta={e['markdown']:e for e in entries}
    files=sorted(p for p in ROOT.rglob('*.md') if not set(p.relative_to(ROOT).parts)&{'.git','.github','templates','node_modules','acervo-local','.venv','dist','test-results'} and p!=lib/'README.md')
    files=[p for p in files if not any(marker in p.read_text() for marker in
           ['Nenhum item adicional foi catalogado nesta seção.', 'Nenhum projeto local foi identificado para esta disciplina.'])]
    outputs={p:lib/'leitura'/p.relative_to(ROOT).with_suffix('.html') for p in files}
    # Remove only obsolete HTML generated by this tool after a Markdown is reused elsewhere.
    for old in (lib/'leitura').rglob('*.html'):
        if old not in outputs.values():old.unlink()
    origins={origin:ROOT/e['markdown'] for e in entries for origin in e['origens']}
    imported=json.loads((ROOT/'catalogo/importacao.json').read_text())
    origins.update({e['origem']:ROOT/e['destino'] for e in imported if (ROOT/e['destino']).suffix=='.md'})
    targets={(ROOT/e['destino']).resolve():origins[e['origem']] for e in imported if e['origem'] in origins}
    tracked={ROOT/p for p in subprocess.check_output(['git','ls-files','-z'],cwd=ROOT).decode().split('\0') if p}
    def shareable(p):
        if p.is_dir():return any(p in f.parents for f in tracked) or lib==p or lib in p.parents
        return p in tracked or lib in p.parents or p in outputs.values()
    records=[];issues=[]
    for md in files:
        rel=md.relative_to(ROOT).as_posix();text=md.read_text();entry=meta.get(rel)
        match=re.search(r'^#\s+(.+)',text,re.M)
        title=entry['titulo'] if entry else (match[1] if match else md.stem)
        group=entry['disciplina'] if entry else (rel.split('/')[1][:2] if rel.startswith('disciplinas/') else 'geral')
        out=outputs[md];out.parent.mkdir(parents=True,exist_ok=True)
        rendered=subprocess.check_output(['pandoc',str(md),'-f','gfm','-t','html5','--wrap=none'],text=True)
        soup=BeautifulSoup(rendered,'html.parser')
        for tag in soup.find_all(['script','iframe','object','embed','style','form','base','meta','link']):tag.decompose()
        for tag in soup.find_all(True):
            for attr in list(tag.attrs):
                if attr.lower().startswith('on') or attr=='srcdoc':del tag[attr]
            for attr in ['href','src']:
                if str(tag.get(attr,'')).lstrip().lower().startswith(('javascript:','vbscript:')):del tag[attr]
        rendered=str(soup)
        toc=''.join('<li><a href="#'+escape(h['id'],quote=True)+'">'+escape(h.get_text())+'</a></li>' for h in soup.find_all(['h2','h3']) if h.get('id'))
        if toc:rendered='<details><summary>Sumário do documento</summary><ul>'+toc+'</ul></details>'+rendered
        def link(m):
            attr,raw=m[1],unquote(m[2]);path,sep,anchor=raw.partition('#')
            if raw.startswith(('http:','https:','mailto:','data:','#')):return m[0]
            target=(md.parent/path).resolve()
            target=targets.get(target,target)
            if '/acervo-local/originais/' in target.as_posix():
                key=target.as_posix().split('/acervo-local/originais/',1)[1]
                target=origins.get(key,target)
            # Library copies of existing Markdown refer to their original source tree.
            if not target.exists() and entry:
                origin=Path(entry['origens'][0]).parent/path
                key=os.path.normpath(str(origin)).replace(os.sep,'/')
                if key in origins:target=origins[key]
            if not target.exists():
                matches={p for key,p in origins.items() if Path(key).name==Path(path).name}
                if len(matches)==1:target=matches.pop()
            if not target.exists() or not shareable(target):
                issues.append({'documento':rel,'referencia':raw})
                # Preserve the reference as text without a broken clickable link.
                return attr+'="'+('#referencia-indisponivel' if attr=='href' else '')+'"'
            target=(lib/'index.html') if target==lib/'README.md' else outputs.get(target,target)
            href=relative(target,out.parent)+('#'+anchor if sep else '')
            return attr+'="'+escape(href,quote=True)+'"'
        rendered=re.sub(r'(href|src)="([^"]+)"',link,rendered)
        foot='<p><a href="'+relative(md,out.parent)+'">Abrir fonte Markdown no Git</a></p>'
        if any(i['documento']==rel for i in issues):foot+='<p id="referencia-indisponivel" class="meta">Algumas referências citam arquivos externos ou não disponíveis nesta biblioteca. O destino original permanece registrado no Markdown.</p>'
        out.write_text(shell(title,'<article>'+foot+rendered+foot+'</article>',out.parent))
        plain=re.sub(r'<[^>]+>',' ',rendered);plain=re.sub(r'\s+',' ',plain)
        records.append({'titulo':title,'disciplina':group,'grupo':names.get(group,group),'markdown':rel,
                        'html':out.relative_to(ROOT).as_posix(),'texto':plain,
                        'formato':entry['formato'] if entry else '.md'})
    records.sort(key=lambda d:(d['disciplina']=='geral',d['disciplina'],d['titulo'].casefold()))
    # Native GitHub navigation with relative Markdown links.
    lines=['# Biblioteca do MBA AI Leadership — 4ABL','',
           '[Portal HTML com busca](index.html) · [Página inicial do repositório](../README.md)','',
           f'{len(records)} documentos Markdown disponíveis para leitura. {len(pending)} fontes aguardam conversão.','',
           'As conversões preservam o conteúdo textual e identificam a origem. PDFs, planilhas e apresentações registram limites de extração; não são resumos. Materiais de terceiros mantêm autoria e direitos. Repositório privado.','']
    for group in sorted({r['disciplina'] for r in records},key=lambda g:(g=='geral',g)):
        lines+=['## '+names.get(group,group),'']
        for record in (r for r in records if r['disciplina']==group):
            target=relative(ROOT/record['markdown'],lib)
            lines.append('- ['+record['titulo'].replace('[','').replace(']','')+']('+target+')')
        lines.append('')
    lines+=['## Cobertura e rastreabilidade','','- [Catálogo das conversões](../catalogo/biblioteca.json).',
            '- [Fontes ainda pendentes](../catalogo/pendencias-conversao.json).',
            '- [Referências não disponíveis na biblioteca](../catalogo/referencias-biblioteca.json).',
            '- [Como atualizar e consultar](../docs/biblioteca.md).','']
    (lib/'README.md').write_text('\n'.join(lines))
    options=''.join('<option value="'+g+'">'+escape(names.get(g,g))+'</option>' for g in sorted({r['disciplina'] for r in records}))
    data=json.dumps(records,ensure_ascii=False).replace('<','\\u003c')
    script='''const docs=DATA;const q=document.querySelector('#q'),group=document.querySelector('#group'),results=document.querySelector('#results'),count=document.querySelector('#count');const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();function update(){const terms=norm(q.value).trim().split(/\s+/).filter(Boolean);let selected=docs.filter(d=>(!group.value||group.value===d.disciplina)&&terms.every(t=>norm(d.titulo+' '+d.texto).includes(t)));results.replaceChildren();count.textContent=selected.length+' documentos encontrados';for(const d of selected){let li=document.createElement('li'),a=document.createElement('a'),meta=document.createElement('div'),preview=document.createElement('p');a.textContent=d.titulo;a.href='../'+d.html;meta.className='meta';meta.textContent=d.grupo+' · '+d.formato+' → Markdown';preview.textContent=d.texto.slice(0,180)+'…';li.append(a,meta,preview);results.append(li);}}q.addEventListener('input',update);group.addEventListener('change',update);update();'''.replace('DATA',data)
    body='<h1>Biblioteca de estudo</h1><p>Leia os materiais por disciplina ou pesquise no conteúdo completo. Cada documento oferece acesso à fonte Markdown.</p><p class="meta">'+str(len(records))+' documentos · '+str(len(pending))+' fontes pendentes de conversão · acesso privado pelo GitHub</p><div class="controls"><input id="q" type="search" placeholder="Buscar no conteúdo: PRD, discovery, correlação…" aria-label="Buscar no conteúdo completo"><select id="group" aria-label="Filtrar por disciplina"><option value="">Todas as disciplinas</option>'+options+'</select></div><p id="count" aria-live="polite"></p><ul id="results"></ul><noscript>Abra o <a href="README.md">índice Markdown</a> para consultar todos os documentos.</noscript><script>'+script+'</script>'
    (lib/'index.html').write_text(shell('Biblioteca · MBA AI Leadership',body,lib))
    (ROOT/'catalogo/referencias-biblioteca.json').write_text(json.dumps(issues,ensure_ascii=False,indent=2)+'\n')
    (ROOT/'catalogo/indice-biblioteca.json').write_text(json.dumps([{k:v for k,v in r.items() if k!='texto'} for r in records],ensure_ascii=False,indent=2)+'\n')
    print(json.dumps({'documentos_markdown':len(records),'fontes_convertidas':sum(len(e['origens']) for e in entries),'pendencias_conversao':len(pending),'referencias_indisponiveis':len(issues)},ensure_ascii=False))

if __name__=='__main__':main()
